package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class ScreenLockPolicyTest{@Test public void locksOnFreshProcessOrTimeout(){assertTrue(SecureActivity.needsAuth(false,-1,1));assertFalse(SecureActivity.needsAuth(true,-1,100));assertFalse(SecureActivity.needsAuth(true,100,30099));assertTrue(SecureActivity.needsAuth(true,100,30100));assertTrue(SecureActivity.needsAuth(true,500,100));}}